namespace sv_2a7b64ca325e4d21918442ba3477459f.Services;

/// <summary>
/// Immutable record cascaded to all components via CascadingValueSource.
/// Replacing the instance (rather than mutating) makes change detection simple.
/// </summary>
public record WarehouseState(string WarehouseId, string WarehouseName)
{
    public static readonly WarehouseState Default = new("wh-1", "Warehouse A");

    public static readonly IReadOnlyList<WarehouseState> All =
    [
        new("wh-1", "Warehouse A"),
        new("wh-2", "Warehouse B"),
        new("wh-3", "Warehouse C"),
    ];
}

namespace sv_2a7b64ca325e4d21918442ba3477459f.Services;

/// <summary>
/// Scoped service (one per circuit) that holds the latest low-stock count
/// and notifies all subscribed components when data changes.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired after <see cref="LowStockCount"/> is updated.
    /// Subscribers must wrap StateHasChanged in InvokeAsync because
    /// this may fire from a timer (non-Blazor thread).
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Refreshes the count for the given warehouse and notifies all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

