@page "/dashboard"
@using sv_2a7b64ca325e4d21918442ba3477459f.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text">
            <strong>@CurrentWarehouse?.WarehouseName</strong>
            <span class="text-muted">(@CurrentWarehouse?.WarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <AlertBadge />
        </h5>
        <p class="card-text">
            Items below minimum stock level: <strong>@AlertService.LowStockCount</strong>
        </p>
        <p class="text-muted mb-0">
            <small>Refreshes every 10 seconds while this page is open.</small>
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private Action? _handler;

    [CascadingParameter]
    private WarehouseState? CurrentWarehouse { get; set; }

    protected override void OnInitialized()
    {
        // Subscribe so we re-render when the alert service fires OnChange
        // (e.g., when the polling loop updates the count).
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;

        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    protected override async Task OnParametersSetAsync()
    {
        // When the cascaded warehouse changes, immediately refresh alerts.
        if (CurrentWarehouse is not null)
        {
            await AlertService.RefreshAsync(CurrentWarehouse.WarehouseId);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                if (CurrentWarehouse is not null)
                {
                    await AlertService.RefreshAsync(CurrentWarehouse.WarehouseId);
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose — timer stops cleanly.
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        AlertService.OnChange -= _handler;
    }
}

